solution.cpp:
#include <iostream>
#include <string>
using namespace std;

string to_str(__int128 x) {
    if (x == 0) return "0";
    string s;
    while (x > 0) { s += char('0' + int(x % 10)); x /= 10; }
    return string(s.rbegin(), s.rend());
}

__int128 s(long long k, long long n) {
    __int128 m = (n - 1) / k;
    return (__int128)k * m * (m + 1) / 2;
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        long long n;
        cin >> n;
        cout << to_str(s(3, n) + s(5, n) - s(15, n)) << "\n";
    }
    return 0;
}
